import {truth,truthy,owned} from './arg-engine.js?v=46';
export function hintsFor(s){const t=truth(s);if(!t.first)return ['翻报告原件、原始收稿、打印委托和春季接力花絮。远景认人还要有交接场记。','请假说法对应3月14日下午。比对原图的独有痕迹；校刊的当周期号要与收稿日期对应。','校刊heshe口令HS032316；原始投稿收录后选折痕与蓝圈缺口。春季BV1Qh4y1p3Ct的01:24可见搬打印机；网盘码0314XSH。交接簿、请假说法与打印委托都核对后，再问朱贵。'];if(!truthy(s,'accounts','shenzhi'))return ['看小范授权里提到的第一次值班旧帖和广播排期。','同是周五，日期不同。要找首次值班那天的末曲，不是前后周的同位置节目。','先读授权及两份来源。首次值班9月13日，对应“夜空中最亮的星”。'];if(!truthy(s,'actions','cacheRestored'))return ['看小范的本地草稿缓存。','草稿编号、修订号和首尾段都要对齐，旧版尾段的结论可能已经过时。','选D0329修订02的1/2，再选同版2/2。恢复后才能确认附件出处。'];if(!truthy(s,'actions','medicalChecked')||!truthy(s,'actions','timelineChecked'))return ['分别核对医务室复查材料和后勤到场工作台；主帖的目击回忆与水房校时回帖也要留着。','用药影响初检可靠性；点名要核对事件日和补录日，工作卡要有本人签收补足身份。','医疗选择R07、0329、初检不能据此排除、不能反推感染批次。先读主帖杰哥的回忆和水房校时回复，到场核对m4/s3/a2/r2；屏显20:43换算为20:41，导出已校正，解释为事后代填。'];if(!owned(s,'clockNote'))return ['回看水房修灯那楼，闲聊里提过后门终端。','目击者记的是屏显，正式导出采用另一时间基准，先对同机号的校时记录。','13号屏显快两分钟，导出已校正。读水房回帖，再把杰哥的屏显回忆与流水串联，不要从导出重复扣两分钟。'];if(!truthy(s,'deductions','memory-clock')&&t.auditReady)return ['把杰哥回忆的时间和后勤导出放在一起。','先排除显示时钟偏差，再对同单号的本人签收。','调查本勾选“杰哥记得的后门屏显”和“食堂终端流水”，核对校时回帖及R0313签收后交叉比对。'];if(t.auditReady&&!truthy(s,'actions','caseReconstructed'))return ['在调查本底部把两层事实串成完整说明。','先对停电窗口与同设备台账，再对原始抽检与结算，最后回看匿名图的来源。','复盘选3月13日20:18—21:06、消毒间专用回路、未检改合格用于结算、朱贵使用by原图改日期匿名投稿。'];if(!s.vault)return ['查草稿附件引用的黑板报与原加密包。','开学日期与夜宵试运行日期不同；维修记录需要同设备、同日，并包含归档。','原包口令20240912，实际解密后保留工作表。维修搜“消毒”且含归档，对20:18—21:06的专用回路停用。'];return ['把已核对的来源放进调查本，选择两张卡提出关系。','到场、漏列、运行、抽检改版、付款依据是五组不同的问题，改版和结算有方向。','点名↔流水、汇总↔复查、台账↔断电用“互相矛盾”；原单→改版用“被改写为”；合同→结算用“被用于结算”。五组后仍需查阅原件复核回函。'];}
